package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="spms_cycle_milestone",uniqueConstraints={@UniqueConstraint(name="uk_spms_milestone_order",columnNames={"agency_id","cycle_id","display_order"}),@UniqueConstraint(name="uk_spms_milestone_type",columnNames={"agency_id","cycle_id","milestone_key"})})
public class PerformanceCycleMilestone extends RspAuditedEntity {public enum Type{PLANNING_OPEN,PLANNING_DUE,APPROVAL_DUE,MONITORING_START,MID_CYCLE_REVIEW,ACCOMPLISHMENT_DUE,RATING_DUE,CALIBRATION_DUE,FINALIZATION_DUE,ACKNOWLEDGMENT_DUE,APPEAL_DUE,CUSTOM}
 @Column(name="cycle_id",nullable=false,length=36)private String cycleId;@Enumerated(EnumType.STRING)@Column(name="milestone_type",nullable=false,length=40)private Type type;@Column(name="milestone_key",nullable=false,length=120)private String milestoneKey;@Column(nullable=false,length=200)private String label;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at")private Instant endsAt;@Column(nullable=false)private boolean required;@Column(name="display_order",nullable=false)private int displayOrder;@Column(length=2000)private String instructions;@Column(name="post_cycle_closeout",nullable=false)private boolean postCycleCloseout;
 protected PerformanceCycleMilestone(){}public PerformanceCycleMilestone(String agency,String cycle,Type type,String key,String label,Instant starts,Instant ends,boolean required,int order,String instructions,boolean post){super(agency);cycleId=requiredText(cycle,"cycleId");this.type=Objects.requireNonNull(type);milestoneKey=requiredText(key,"milestoneKey").toUpperCase(Locale.ROOT);this.label=requiredText(label,"label");startsAt=Objects.requireNonNull(starts,"startsAt");endsAt=ends;if(ends!=null&&ends.isBefore(starts))throw new IllegalArgumentException("milestone endsAt cannot precede startsAt");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");this.required=required;displayOrder=order;this.instructions=optionalText(instructions);postCycleCloseout=post;if(type!=Type.CUSTOM&&!milestoneKey.equals(type.name()))throw new IllegalArgumentException("Controlled milestone key must match its type");}
 public String getCycleId(){return cycleId;}public Type getType(){return type;}public String getMilestoneKey(){return milestoneKey;}public String getLabel(){return label;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public boolean isRequired(){return required;}public int getDisplayOrder(){return displayOrder;}public String getInstructions(){return instructions;}public boolean isPostCycleCloseout(){return postCycleCloseout;}
}
